import{_ as a,m as o,n,q as l}from"./chunks/framework.DMDh-7Lg.js";const y=JSON.parse('{"title":"Autocomplete","description":"","frontmatter":{},"headers":[],"relativePath":"guides/autocomplete.md","filePath":"guides/autocomplete.md"}'),e={name:"guides/autocomplete.md"};function t(p,s,c,r,i,F){return o(),n("div",null,[...s[0]||(s[0]=[l(`<h1 id="autocomplete" tabindex="-1">Autocomplete <a class="header-anchor" href="#autocomplete" aria-label="Permalink to &quot;Autocomplete&quot;">​</a></h1><p>Klix includes command and argument completion through <code>KlixCompleter</code>, built on top of prompt-toolkit.</p><p>This guide explains what you get automatically, how to add your own completions, and where the edges are. For the parser that consumes completed text, see <a href="./../concepts/router">Router</a>.</p><h2 id="what-works-automatically" tabindex="-1">What Works Automatically <a class="header-anchor" href="#what-works-automatically" aria-label="Permalink to &quot;What Works Automatically&quot;">​</a></h2><p>When the app starts, it creates a <code>KlixCompleter</code> with:</p><ul><li>all registered command names</li><li>all registered aliases</li><li>any custom completers you add</li></ul><p>That means slash commands autocomplete out of the box.</p><p>If you register:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">command</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/deploy</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> aliases</span><span style="color:#89DDFF;">=[</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/ship</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">])</span></span>
<span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> deploy</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">)</span><span style="color:#89DDFF;"> -&gt;</span><span style="color:#89DDFF;"> None:</span></span>
<span class="line"><span style="color:#BABED8;">    ...</span></span></code></pre></div><p>Typing <code>/de</code> or <code>/sh</code> will offer completions in an interactive terminal.</p><h2 id="add-custom-argument-completion" tabindex="-1">Add Custom Argument Completion <a class="header-anchor" href="#add-custom-argument-completion" aria-label="Permalink to &quot;Add Custom Argument Completion&quot;">​</a></h2><p>Use the app helper for argument-specific completions:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#BABED8;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">add_completer</span><span style="color:#89DDFF;">(</span></span>
<span class="line"><span style="color:#89DDFF;">    &quot;</span><span style="color:#C3E88D;">/deploy</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#C792EA;">    lambda</span><span style="color:#BABED8;font-style:italic;"> text</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> session</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> [</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">staging</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">production</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">preview</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">],</span></span>
<span class="line"><span style="color:#89DDFF;">)</span></span></code></pre></div><p>The callable receives:</p><ul><li>the current input text</li><li>the active session</li></ul><p>That gives you enough context to compute suggestions dynamically.</p><h2 id="example-environment-aware-completion" tabindex="-1">Example: Environment-Aware Completion <a class="header-anchor" href="#example-environment-aware-completion" aria-label="Permalink to &quot;Example: Environment-Aware Completion&quot;">​</a></h2><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> environment_completer</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">text</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> str</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">)</span><span style="color:#89DDFF;"> -&gt;</span><span style="color:#BABED8;"> list</span><span style="color:#89DDFF;">[</span><span style="color:#FFCB6B;">str</span><span style="color:#89DDFF;">]:</span></span>
<span class="line"><span style="color:#BABED8;">    choices </span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;"> [</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">staging</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">production</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">preview</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">]</span></span>
<span class="line"><span style="color:#BABED8;">    token </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> text</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">split</span><span style="color:#89DDFF;">()[-</span><span style="color:#F78C6C;">1</span><span style="color:#89DDFF;">]</span><span style="color:#89DDFF;font-style:italic;"> if</span><span style="color:#BABED8;"> text</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">split</span><span style="color:#89DDFF;">()</span><span style="color:#89DDFF;font-style:italic;"> else</span><span style="color:#89DDFF;"> &quot;&quot;</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">    return</span><span style="color:#89DDFF;"> [</span><span style="color:#BABED8;">choice </span><span style="color:#89DDFF;font-style:italic;">for</span><span style="color:#BABED8;"> choice </span><span style="color:#89DDFF;font-style:italic;">in</span><span style="color:#BABED8;"> choices </span><span style="color:#89DDFF;font-style:italic;">if</span><span style="color:#BABED8;"> choice</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">startswith</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">token</span><span style="color:#89DDFF;">)]</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">add_completer</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/deploy</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#82AAFF;"> environment_completer</span><span style="color:#89DDFF;">)</span></span></code></pre></div><p>Now typing:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>/deploy pr</span></span></code></pre></div><p>can suggest <code>production</code> and <code>preview</code>.</p><h2 id="how-completion-is-chosen" tabindex="-1">How Completion Is Chosen <a class="header-anchor" href="#how-completion-is-chosen" aria-label="Permalink to &quot;How Completion Is Chosen&quot;">​</a></h2><p>At a high level:</p><ol><li>If the first token looks like a command, Klix offers command and alias matches.</li><li>If there is a command-specific completer for that command, Klix also asks it for suggestions.</li><li>Suggestions are filtered against the current token.</li></ol><p>This is intentionally simpler than a full shell completion engine. It works well for most app-level use cases.</p><h2 id="fuzzy-matching" tabindex="-1">Fuzzy Matching <a class="header-anchor" href="#fuzzy-matching" aria-label="Permalink to &quot;Fuzzy Matching&quot;">​</a></h2><p>Command completion uses fuzzy matching behavior from prompt-toolkit where appropriate, so partial command prefixes work naturally.</p><p>The <code>session.ui.input.fuzzy(...)</code> widget is a separate feature. It provides an interactive selector for values during a command flow and does not replace prompt-level completion. See <a href="./../components/input">Components: Input</a>.</p><h2 id="practical-pattern" tabindex="-1">Practical Pattern <a class="header-anchor" href="#practical-pattern" aria-label="Permalink to &quot;Practical Pattern&quot;">​</a></h2><p>Autocomplete works best when combined with clear command design:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">command</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/logs</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> help</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Show service logs</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> logs</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">)</span><span style="color:#89DDFF;"> -&gt;</span><span style="color:#89DDFF;"> None:</span></span>
<span class="line"><span style="color:#BABED8;">    ...</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> logs_completer</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">text</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> str</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">)</span><span style="color:#89DDFF;"> -&gt;</span><span style="color:#BABED8;"> list</span><span style="color:#89DDFF;">[</span><span style="color:#FFCB6B;">str</span><span style="color:#89DDFF;">]:</span></span>
<span class="line"><span style="color:#BABED8;">    services </span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;"> [</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">api</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">worker</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">scheduler</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">]</span></span>
<span class="line"><span style="color:#BABED8;">    token </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> text</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">split</span><span style="color:#89DDFF;">()[-</span><span style="color:#F78C6C;">1</span><span style="color:#89DDFF;">]</span><span style="color:#89DDFF;font-style:italic;"> if</span><span style="color:#BABED8;"> text</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">split</span><span style="color:#89DDFF;">()</span><span style="color:#89DDFF;font-style:italic;"> else</span><span style="color:#89DDFF;"> &quot;&quot;</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">    return</span><span style="color:#89DDFF;"> [</span><span style="color:#BABED8;">service </span><span style="color:#89DDFF;font-style:italic;">for</span><span style="color:#BABED8;"> service </span><span style="color:#89DDFF;font-style:italic;">in</span><span style="color:#BABED8;"> services </span><span style="color:#89DDFF;font-style:italic;">if</span><span style="color:#BABED8;"> service</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">startswith</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">token</span><span style="color:#89DDFF;">)]</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">add_completer</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/logs</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#82AAFF;"> logs_completer</span><span style="color:#89DDFF;">)</span></span></code></pre></div><p>That gives users both discovery and speed without making the parser more complex.</p><h2 id="current-limitations" tabindex="-1">Current Limitations <a class="header-anchor" href="#current-limitations" aria-label="Permalink to &quot;Current Limitations&quot;">​</a></h2><ul><li>Completion is not schema-driven. Klix does not inspect Pydantic fields to build suggestions automatically.</li><li>The parser is still whitespace-based, so completion does not imply shell-like quoting support.</li><li>CI and non-interactive environments do not expose the full prompt-toolkit completion experience.</li></ul><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ul><li>Returning huge unfiltered suggestion lists. Filter against the active token when possible.</li><li>Assuming custom completers run for aliases separately. They are attached to the registered command name you provide.</li><li>Treating completion as validation. The router and schema validation still decide what is legal.</li></ul><h2 id="related-reading" tabindex="-1">Related Reading <a class="header-anchor" href="#related-reading" aria-label="Permalink to &quot;Related Reading&quot;">​</a></h2><ul><li><a href="./adding-commands">Adding Commands</a></li><li><a href="./../concepts/router">Concepts: Router</a></li><li><a href="./../reference/api">Reference: API</a></li></ul>`,38)])])}const d=a(e,[["render",t]]);export{y as __pageData,d as default};
